package net.civeira.phylax.feature.identity.user.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class FederatedProviderVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property federated provider of user ")
  void test_federated_provider_v_o_builder() {
    Assertions.assertFalse(FederatedProviderVO.nullValue().getFederatedProvider().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(FederatedProviderVO.tryFrom(null).getFederatedProvider().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one",
        FederatedProviderVO.from("one").getFederatedProvider().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> FederatedProviderVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", FederatedProviderVO.from("one").toString());
  }
}
